  ACTIVE
  DISABLED
}
```

### Phase 3: Copy DB Schema

```prisma
// apps/copy-api/prisma/schema.prisma

model SignalProvider {
  id                String   @id @default(uuid())
  tenantId          String
  userId            String   // 关联 Tenant DB 的用户
  tradingAccountId  String   // 信号源交易账户
  displayName       String
  description       String?
  profitSharePercent Decimal @default(20)
  status            ProviderStatus @default(PENDING)
  statistics        Json?    // 缓存的统计数据
  subscriptions     Subscription[]
  copyTrades        CopyTrade[]
  settlements       Settlement[]
  createdAt         DateTime @default(now())
  updatedAt         DateTime @updatedAt

  @@index([tenantId])
  @@index([status])
}

enum ProviderStatus {
  PENDING     // 待审核
  ACTIVE      // 已激活
  SUSPENDED   // 已暂停
  REJECTED    // 已拒绝
}

model Subscription {
  id                String   @id @default(uuid())
  tenantId          String
  providerId        String
  provider          SignalProvider @relation(fields: [providerId], references: [id])
  followerId        String   // 跟单者用户 ID
  tradingAccountId  String   // 跟单者交易账户
  copyMode          CopyMode
  fixedLots         Decimal?
  lotMultiplier     Decimal?
  maxLots           Decimal  @default(1)
  maxPositions      Int      @default(10)
  blacklistSymbols  String[] @default([])
  stopLossPercent   Decimal?
  status            SubscriptionStatus @default(ACTIVE)
  highWaterMark     Decimal  @default(0)
  copyTrades        CopyTrade[]
  settlements       Settlement[]
  createdAt         DateTime @default(now())
  updatedAt         DateTime @updatedAt

  @@unique([tenantId, providerId, followerId])
  @@index([tenantId])
  @@index([providerId])
}

enum CopyMode {
  FIXED_LOT
  PROPORTIONAL
}

enum SubscriptionStatus {
  ACTIVE
  PAUSED
  CANCELLED
}

model CopyTrade {
  id               String   @id @default(uuid())
  tenantId         String
  subscriptionId   String
  subscription     Subscription @relation(fields: [subscriptionId], references: [id])
  providerId       String
  provider         SignalProvider @relation(fields: [providerId], references: [id])
